لارشاد والاصلاح كشجرة طيبة اصلها ثابت وفرعها في السماء تؤتي اكلها كل حين باذن ربها . جمعية الارشاد والاصلاح صاحبة القيم والمبادئ الطيبة رغم كل العواصف لا تزال بعون الله تعالى راسخة وثابتة على المنهج الاسلام الذي فيه النجاة والسعادة . جمعية الارشاد والاصلاح نموذج ناجح في بناء وطن آمن مستقر ينعم بالامن والايمان ويكون فيه الانسان مكرم ومعزز ومصان اي انسان كان ...','[{\"from_year\":\"2017\",\"to_year\":\"2020\",\"work_description\":\"\\u0645\\u0646\\u0633\\u0642\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0646\\u0627\\u0637\\u0642 + \\u0642\\u0633\\u0645 \\u0642\\u0637\\u0627\\u0641 - \\u0645\\u0631\\u0643\\u0632 \\u0627\\u0644\\u0627\\u0631\\u0634\\u0627\\u062f \\u0627\\u0644\\u0637\\u0628\\u064a+ \\u0642\\u0633\\u0645 \\u0627\\u0644\\u062f\\u0639\\u0648\\u0629\"},{\"from_year\":\"2013\",\"to_year\":\"2017\",\"work_description\":\"\\u0627\\u0644\\u062f\\u0639\\u0648\\u0629 + \\u062f\\u0648\\u0631\\u0627\\u062a \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0645\\u0647\\u0646\\u064a + \\u062f\\u0627\\u0626\\u0631\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u062e\\u064a\\u0631\\u064a\"},{\"from_year\":\"2009\",\"to_year\":\"2013\",\"work_description\":\"\\u0627\\u0644\\u0628\\u062f\\u0621 \\u0645\\u0646 2006 \\u0628\\u062f\\u0627\\u064a\\u0629 \\u0645\\u062a\\u0627\\u0628\\u0639\\u0629 \\u0627\\u0646\\u0634\\u0627\\u0621 \\u0648\\u0628\\u0646\\u0627\\u0621 \\u0627\\u0644\\u0645\\u0634\\u0631\\u0648\\u0639 \\u062d\\u062a\\u0649 2008 - \\u0645\\u0646 2008 - 2009 \\u0627\\u0644\\u062a\\u062f\\u0631\\u064a\\u0628 \\u0627\\u0644\\u0645\\u0647\\u0646\\u064a + \\u0627\\u0644\\u0639\\u0645\\u0644 \\u0627\\u0644\\u062e\\u064a\\u0631\\u064a ( \\u0645\\u0633\\u0627\\u0639\\u062f\\u0627\\u062a + \\u0643\\u0641\\u0627\\u0644\\u0627\\u062a \\u0627\\u064a\\u062a\\u0627\\u0645 ...)\"},{\"from_year\":\"2005\",\"to_year\":\"2009\",\"work_description\":\"\"},{\"from_year\":\"\",\"to_year\":\"\",\"work_description\":\"\"},{\"from_year\":\"\",\"to_year\":\"\",\"w